// tile.jsx — Hello Note's face on the deck (2×2 cells).
import { Stack, Text } from 'bombers/ui';

export function tile({ state }) {
  const [note] = state('note', 'hello from the store!', { persist: true });

  return (
    <Stack align="center" justify="center" gap={4} style={{ width: '100%', height: '100%' }}>
      <Text size={15}>{note}</Text>
      <Text variant="faint">tap to change</Text>
    </Stack>
  );
}

