// modal.jsx — pick what the tile says (shares the 'note' state key).
import { Button, Stack, Text } from 'bombers/ui';

const NOTES = [
  'hello from the store!',
  'have a lovely day',
  'drink some water',
  'you got this',
];

export function modal({ state }) {
  const [note, setNote] = state('note', 'hello from the store!', { persist: true });

  return (
    <Stack gap={12}>
      <Text variant="muted">Pick what the tile says:</Text>
      <Stack gap={6}>
        {NOTES.map((n) => (
          <Button key={n} variant={n === note ? 'primary' : undefined} onClick={() => setNote(n)}>
            {n}
          </Button>
        ))}
      </Stack>
    </Stack>
  );
}
